      "stance": "risk",
      "quote": "buried in fine print or behind small icons on Adobe's website"
    },
    {
      "ref": "[2]",
      "area": "money",
      "claim": "A parent reports that Adobe makes the cancellation process unnecessarily complicated to deter users from canceling.",
      "stance": "risk",
      "quote": "making the cancellation process unnecessarily complicated"
    },
