      "ref": "[7]",
      "area": "money",
      "claim": "A parent reports that the settlement requires Adobe to give subscribers easy ways to cancel and to clearly disclose any early termination fee before enrollment.",
      "stance": "mitigation",
      "quote": "the order requires Adobe to give subscribers easy ways to cancel. Adobe must also clearly disclose any ETF and how it is calculated before enrolling customers"
    },
    {
      "ref": "[7]",
      "area": "money",
      "claim": "A parent reports that Adobe must send a reminder before a free trial longer than seven days turns into a paid plan with an early termination fee.",
      "stance": "mitigation",
      "quote": "must also send a reminder before a long trial converts to a paid plan with an ETF"
    },
    {
      "ref": "[1]",
      "area": "data",
      "claim": "A parent reports that the FTC complaint alleges Adobe failed to disclose all terms and used deceptive practices that violate the Restore Online Shoppers' Confidence Act.",
      "stance": "risk",
      "quote": "violate the Restore Online Shoppers' Confidence Act (ROSCA), which requires clear disclosure of all terms and a straightforward cancellation mechanism"
    },
